#!/usr/bin/env python3
"""Stamp the provenance header onto a copy of index.html for the site repo.

    sync_countdown.py <source index.html> <destination path> <sha> [date] [--force]

Writes the destination and reports whether anything meaningful changed. The
comparison ignores the header itself, so a re-run on an unchanged page does not
manufacture a commit whose only difference is today's date.

--force writes the header even when the body already matches. That is how the
first sync replaces a header written by hand before this workflow existed;
without it, an unchanged body means an untouched header, forever.

Prints `changed=true|false` to $GITHUB_OUTPUT when running under Actions, and a
human-readable line either way.
"""
import datetime
import io
import os
import re
import sys

# HTML doctypes are case-insensitive, and this page spells it <!DOCTYPE html>
# while its siblings use lowercase. Match either and reuse whichever the source
# actually has, so syncing never rewrites that line.
DOCTYPE_RE = re.compile(r"^\s*<!doctype\s+html\s*>", re.IGNORECASE)

HEADER = """
<!--
  Weekly Countdown — a dial showing how much of the week has elapsed toward a
  recurring weekly moment (default: Thursday 3:00 AM). Single-file copy.

  Synced {date} from github.com/arnaudin/weekly-countdown @ {sha}, by that
  repo's .github/workflows/sync-to-site.yml. Do not edit this file: edit the
  source and the next push overwrites this copy.

  No front matter, so Jekyll passes it through untouched. No build, no
  dependencies, and no network requests at all — system fonts only, and the
  favicon is an inline data URI.

  The day, time, and label are editable in the page (saved to localStorage)
  and can also be set by query string, e.g. ?day=1&time=09:00&label=Sprint
-->"""


def split_doctype(text):
    """(doctype, rest), or (None, text) when there is no leading doctype."""
    match = DOCTYPE_RE.match(text)
    if not match:
        return None, text
    return match.group(0), text[match.end():]


def body_of(text):
    """The document after any leading doctype and provenance comment."""
    doctype, rest = split_doctype(text)
    if doctype is None:
        return text
    if rest.lstrip().startswith("<!--"):
        end = rest.find("-->")
        if end != -1:
            return rest[end + 3:]
    return rest


def main():
    args = [a for a in sys.argv[1:] if a != "--force"]
    force = "--force" in sys.argv[1:]
    if len(args) not in (3, 4):
        sys.exit(__doc__)
    src_path, dst_path, sha = args[:3]
    date = args[3] if len(args) == 4 else datetime.date.today().isoformat()

    source = io.open(src_path, encoding="utf-8").read()
    doctype, _ = split_doctype(source)
    if doctype is None:
        sys.exit("refusing to sync: %s does not start with a <!doctype html>" % src_path)
    if source.lstrip().startswith("---"):
        sys.exit("refusing to sync: %s has front matter; Jekyll would render it" % src_path)

    body = body_of(source)
    new = doctype + HEADER.format(date=date, sha=sha) + body

    try:
        old = io.open(dst_path, encoding="utf-8").read()
    except IOError:
        old = None

    changed = old is None or body_of(old) != body
    write = changed or force

    if write:
        parent = os.path.dirname(dst_path)
        if parent:
            os.makedirs(parent, exist_ok=True)
        io.open(dst_path, "w", encoding="utf-8").write(new)

    if changed:
        print("changed")
    elif force:
        print("no body change, but --force rewrote the header")
    else:
        print("no change: the copy already matches the source")

    out = os.environ.get("GITHUB_OUTPUT")
    if out:
        with io.open(out, "a", encoding="utf-8") as fh:
            fh.write("changed=%s\n" % ("true" if write else "false"))


if __name__ == "__main__":
    main()
